# ===== د قرآني کیسو او علمي الهامونو د معلوماتو جوړول =====


def make_lesson(item, index, category):
    # د موضوعاتو بېلابېل جوړښتونه په خوندي ډول تنظیمول
    if len(item) == 10:
        number, title, surah, reference, story, moral, science, caution, activity, quiz = item
    elif len(item) == 9:
        if isinstance(item[0], int):
            number, title, surah, reference, story, moral, science, caution, activity = item
        else:
            title, surah, reference, story, moral, science, caution, activity, quiz = item
    elif len(item) == 8:
        title, surah, reference, story, moral, science, caution, activity = item
        quiz = [
            "له دې موضوع څخه کوم اخلاقي درس زده کېدای شي؟",
            "دا زده کړه په ورځني ژوند کې څنګه عملي کېدای شي؟"
        ]
    else:
        raise ValueError(
            f"د موضوع {index} جوړښت لا نه پېژندل کېږي: {len(item)} برخې"
        )

    return {
        "id": f"quran_inspiration_{index:03d}",
        "number": index,
        "category": category,
        "title": title,
        "surah": surah,
        "reference": reference,
        "story": story,
        "moral": moral,
        "scientific_inspiration": science,
        "interpretation_note": caution,
        "activity": activity,
        "quiz": quiz if isinstance(quiz, list) else [str(quiz)]
    }


all_lessons = []
seen = set()

for category, items in [
    ("اصلي موضوعات", topics),
    ("اضافي موضوعات", extra),
    ("عمومي موضوعات", generic_topics),
]:
    for item in items:
        title = item[1] if len(item) == 9 else item[0]
        key = re.sub(r"\s+", " ", str(title)).strip()

        if key in seen:
            continue

        seen.add(key)
        all_lessons.append(make_lesson(item, len(all_lessons) + 1, category))

OUT.parent.mkdir(parents=True, exist_ok=True)
OUT.write_text(
    json.dumps(all_lessons, ensure_ascii=False, indent=2),
    encoding="utf-8"
)

print("د قرآني الهامونو فایل جوړ شو.")
print("فایل:", OUT)
print("د درسونو شمېر:", len(all_lessons))
print("د فایل اندازه:", round(OUT.stat().st_size / 1024, 2), "KB")
